/**
 * VATPreviewLineItemSchema
 *
 * Line item in a VAT preview response.
 *
 * **One line per distinct unit price**, not per requested tier: a cart mixing price
 * categories has no single ``unit_price_gross``, and collapsing it to one would be the
 * exact number the buyer is not charged. A tier whose seats all cost the same — every
 * tier without a category map — still yields exactly one line, unchanged.
 */
export type VatPreviewLineItemSchema = {
    /**
     * Tier Name
     */
    tier_name: string;
    /**
     * Price Category Name
     *
     * The price category this line's seats are painted with. Null for general admission, unpainted seats, and any tier without a category map.
     */
    price_category_name?: string | null;
    /**
     * Ticket Count
     */
    ticket_count: number;
    /**
     * Unit Price Gross
     */
    unit_price_gross: string;
    /**
     * Unit Price Net
     */
    unit_price_net: string;
    /**
     * Unit Vat
     */
    unit_vat: string;
    /**
     * Vat Rate
     */
    vat_rate: string;
    /**
     * Line Net
     */
    line_net: string;
    /**
     * Line Vat
     */
    line_vat: string;
    /**
     * Line Gross
     */
    line_gross: string;
};

/**
 * VATPreviewResponseSchema
 *
 * Response from the VAT preview endpoint.
 */
export type VatPreviewResponseSchema = {
    /**
     * Vat Id Valid
     */
    vat_id_valid?: boolean | null;
    /**
     * Vat Id Validation Error
     */
    vat_id_validation_error?: string | null;
    /**
     * Reverse Charge
     */
    reverse_charge: boolean;
    /**
     * Line Items
     */
    line_items: Array<VatPreviewLineItemSchema>;
    /**
     * Total Net
     */
    total_net: string;
    /**
     * Total Vat
     */
    total_vat: string;
    /**
     * Total Gross
     */
    total_gross: string;
    /**
     * Currency
     */
    currency: string;
    /**
     * Virtual B2C Disclaimer
     *
     * Virtual event, cross-border EU B2C buyer (#869): VAT is charged at the organizer's rate as an interim treatment; the buyer's country's rate may legally apply via OSS. The frontend should render a disclaimer.
     */
    virtual_b2c_disclaimer?: boolean;
};

/**
 * VATPreviewItemSchema
 *
 * Single item in a VAT preview request.
 */
export type VatPreviewItemSchema = {
    /**
     * Tier Id
     */
    tier_id: string;
    /**
     * Count
     */
    count: number;
    /**
     * Price Category Id
     *
     * Zone the best-available picker draws from: a price category painted in the tier's sector and priced by its `category_prices` map. Null = the tier's whole pool.
     */
    price_category_id?: string | null;
    /**
     * Seat Ids
     *
     * Seats chosen for this line, in cart order. Required to preview a tier that prices seats per category — without it the preview charges the tier's flat price for every ticket and will disagree with checkout. Omit for general admission. When present it must hold exactly `count` ids.
     */
    seat_ids?: Array<string>;
};

/**
 * VATPreviewRequestSchema
 *
 * Request payload for the VAT preview endpoint.
 */
export type VatPreviewRequestSchema = {
    billing_info: BuyerBillingInfoSchema;
    /**
     * Items
     */
    items: Array<VatPreviewItemSchema>;
    /**
     * Discount Code
     *
     * Optional discount code
     */
    discount_code?: string | null;
    /**
     * Price Per Ticket
     *
     * PWYC price override
     */
    price_per_ticket?: number | string | null;
};

