    /**
     * Pwyc Max
     */
    pwyc_max?: number | string | null;
    /**
     * Vat Rate
     *
     * VAT rate override. Null = use org default.
     */
    vat_rate?: number | string | null;
    /**
     * Vat Exemption Reason
     */
    vat_exemption_reason?: string;
    /**
     * Currency
     */
